  private Throwable handlePendingSubscriptions(final Connection conn) {
    return switch (conn.lifecycle) {
      case ACTIVE -> handleActivePendingSubscriptions(conn);
      case PING_FAILED -> claimFailedPing(conn);
      case ESCALATED -> null;
    };
  }
